const PATIENTS_CONFIG = [
  { id:1, name:"Madeleine Dupont", address:"12 rue des Lilas, 75012 Paris",
    cameras:["zosi"], icon:"👵", initials:"MD", avatarCls:"av-blue" },
  { id:2, name:"Robert Martin", address:"8 avenue Victor Hugo, 69006 Lyon",
    cameras:[], icon:"👴", initials:"RM", avatarCls:"av-teal" }
];
const now = Math.floor(Date.now() / 1000);
const h24 = now - 86400;

// HTTP nodes auto-split JSON arrays → each item = one event
const lastEvts  = $('Frigate Dernier Event').all().map(i => i.json);
const todayEvts = $('Frigate Events 24h').all().map(i => i.json);

const enriched = PATIENTS_CONFIG.map(p => {
  let status = p.cameras.length === 0 ? 'inactive' : 'normal';
  let eventsToday = 0;
  let lastActivity = 'Aucune activité récente';
  let lastEventId  = null;

  if (p.cameras.length > 0) {
    eventsToday = todayEvts.filter(e => p.cameras.includes(e.camera)).length;
    const pLast = lastEvts.find(e => p.cameras.includes(e.camera));
    if (pLast) {
      lastEventId = pLast.id;
      const d = new Date(pLast.start_time * 1000);
      const hh = d.getHours().toString().padStart(2,'0');
      const mm = d.getMinutes().toString().padStart(2,'0');
      lastActivity = d.toDateString() === new Date().toDateString()
        ? `Aujourd'hui à ${hh}:${mm}`
        : d.toLocaleDateString('fr-FR') + ` à ${hh}:${mm}`;
      status = pLast.start_time < h24 ? 'alert' : 'normal';
    } else { status = 'alert'; }
  }

  const labels = {normal:'Normal', alert:'Alerte', urgent:'Urgence', inactive:'Inactif'};
  return { ...p, status, statusLabel: labels[status]||status,
           lastActivity, lastEventId, eventsToday };
});

return [{ json: { patients: enriched } }];
